cd /tmp/mp && cat > /tmp/mp/mk.py <<'PYEOF'
import sys, json
sys.path.insert(0,'/tmp/mp')
import h2, h
GROW = open('/tmp/mp/grow.py').read().split('def moves')[1]
def policy_src(K, sched):
    # sched: dict turn -> list of (x,y,d) OR raw string
    return f"""
K = {K}
SCHED = {json.dumps({str(k):v for k,v in sched.items()})}
def _grow{GROW}
def moves(turn, pid, W, H, prod, owner, strength):
    if turn < K: return _grow(turn,pid,W,H,prod,owner,strength)
    s = SCHED.get(str(turn))
    if s is None: return []
    if isinstance(s,str): return s
    return [tuple(x) for x in s]
"""
def go(sched, K=40, frames=None, seed=1, w=12, hh=8, rows=None, cols=None, nplayers=1, extra=None):
    src = policy_src(K, sched)
    so,se,rep,logs,dbgs = h2.runpol(seed,w,hh,[src],nplayers=nplayers,extra=extra)
    if frames is None: frames=[K,K+1]
    for f in frames: h.grid(rep,f,rows=rows,cols=cols)
    if logs: print('LOGS:',logs)
    return rep
